     1	import {describe, expect, it} from '@jest/globals';
     2	import {createChatOrchestrator} from './chatOrchestrator.js';
     3	import type {AIProvider, MessageChunk, SendMessageParams} from '../types/ai.js';
     4	import type {ChatSession} from '../types/session.js';
     5	import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
     6	
     7	const SENT_AT = '2026-01-01T00:00:00.000Z';
     8	
     9	function createSession(content: string): ChatSession {
    10	  return {
    11	    sessionId: 's1',
    12	    userId: 'u1',
    13	    entries: [{role: 'user', content, timestamp: SENT_AT}],
    14	  };
    15	}
    16	
    17	function createMockProvider(response: string): AIProvider {
    18	  return {
    19	    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
    20	      yield {type: 'text', text: response};
    21	      yield {type: 'stop', stopReason: 'end_turn'};
    22	    },
    23	    async generateStructured<T>(): Promise<T> {
    24	      return {} as T;
    25	    },
    26	  };
    27	}
    28	
    29	const promptBuilder = new PromptBuilder({
    30	  baseSystemPrompt: 'You are HAL.',
    31	  systemPromptSuffix: 'Be precise.',
    32	  contextConfig: {
    33	    historyLength: 10,
    34	    includeTimestamps: false,
    35	    includeSystemPrompt: true,
    36	  },
    37	});
    38	
    39	describe('beforeSession throwing', () => {
    40	  it('runs onError and afterSession when beforeSession throws', async () => {
    41	    const errorToThrow = new Error('Database connection failed in beforeSession');
    42	
    43	    let caughtError: Error | undefined;
    44	    let afterSessionRan = false;
    45	
    46	    const orchestrator = createChatOrchestrator(createMockProvider('hello back'), promptBuilder, undefined, {
    47	      hooks: {
    48	        beforeSession: async () => {
    49	          throw errorToThrow;
    50	        },
    51	        onError: async (_session, error) => {
    52	          caughtError = error;
    53	        },
    54	        afterSession: async () => {
    55	          afterSessionRan = true;
    56	        },
    57	      },
    58	    });
    59	
    60	    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow(
    61	      'Database connection failed in beforeSession'
    62	    );
    63	
    64	    expect(caughtError).toBe(errorToThrow);
    65	    expect(afterSessionRan).toBe(true);
    66	  });
    67	});
